INSERT INTO public.projects (id, name, plain_summary, details, department, sector, state, district, latitude, longitude, budget_inr, status, start_date, planned_end_date, actual_end_date, verification_status, confidence, last_verified_at, published, source_origin)
VALUES
('11111111-1111-1111-1111-111111111109','Mumbai Metro Line 3 (Aqua Line) full corridor','An underground metro line running from Cuffe Parade to Aarey in Mumbai, opened in stages.','This is Mumbai''s first fully underground metro line. It runs about 33 km with 27 stations and links the southern business district with the airport and the western suburbs. Sections opened in stages rather than all at once.','Mumbai Metro Rail Corporation','Urban transport','Maharashtra','Mumbai',19.0330,72.8697,37000000000,'ongoing','2016-08-01','2025-12-31',NULL,'verified',0.90,now(),true,'official'),
('11111111-1111-1111-1111-111111111110','Pune Metro Line 1 and 2 extensions','New metro stretches added to Pune''s existing two metro lines.','Pune''s metro opened in parts from 2022. Extensions add stations towards Chandani Chowk and Vanaz, and towards Ramwadi, so more of the city is within walking distance of a station.','Maharashtra Metro Rail Corporation','Urban transport','Maharashtra','Pune',18.5204,73.8567,11400000000,'ongoing','2019-04-01','2026-06-30',NULL,'verified',0.84,now(),true,'official'),
('11111111-1111-1111-1111-111111111111','Nagpur Metro Phase 2','An extension of Nagpur''s metro towards the outskirts of the city.','Phase 2 stretches the existing metro further out on all four corridors, so people living in the suburbs can reach the city centre without changing vehicles.','Maharashtra Metro Rail Corporation','Urban transport','Maharashtra','Nagpur',21.1458,79.0882,68000000000,'delayed','2020-01-01','2025-03-31',NULL,'pending_review',0.66,now(),true,'official'),
('11111111-1111-1111-1111-111111111112','Hyderabad Metro Phase 2 corridors','New metro corridors planned across Hyderabad, including a link to the airport.','Phase 2 adds several corridors to the existing Hyderabad metro. The plan includes a direct line towards the airport and links to fast-growing areas in the west of the city.','Hyderabad Airport Metro Limited','Urban transport','Telangana','Hyderabad',17.3850,78.4867,247000000000,'planned','2024-06-01','2031-12-31',NULL,'pending_review',0.58,now(),true,'official'),
('11111111-1111-1111-1111-111111111113','Ahmedabad Metro Phase 2 to Gandhinagar','A metro extension connecting Ahmedabad with the state capital, Gandhinagar.','Phase 2 continues the Ahmedabad metro north into Gandhinagar, including stops near the secretariat and the university area. It is meant to cut the daily commute between the two cities.','Gujarat Metro Rail Corporation','Urban transport','Gujarat','Gandhinagar',23.2156,72.6369,58000000000,'completed','2019-03-01','2024-09-30','2024-09-16','verified',0.88,now(),true,'official'),
('11111111-1111-1111-1111-111111111114','Surat Metro Phase 1','Two metro lines being built across Surat.','Surat is getting two metro corridors, one running east to west through the older city and one linking the diamond and textile work areas. Work has been running since 2021.','Gujarat Metro Rail Corporation','Urban transport','Gujarat','Surat',21.1702,72.8311,120200000000,'ongoing','2021-01-01','2027-12-31',NULL,'verified',0.82,now(),true,'official'),
('11111111-1111-1111-1111-111111111115','Patna Metro Corridor 2 underground section','An underground metro stretch being tunnelled under Patna.','Corridor 2 runs across Patna with an underground stretch of roughly 7.4 km. Tunnelling is the slowest and most expensive part of the work, so this section decides when the line can open.','Patna Metro Rail Corporation','Urban transport','Bihar','Patna',25.5941,85.1376,135000000000,'delayed','2019-10-01','2025-08-31',NULL,'verified',0.79,now(),true,'official'),
('11111111-1111-1111-1111-111111111116','Bharatmala Pariyojana highway stretches in Rajasthan','National highway building in Rajasthan under the central Bharatmala programme.','Bharatmala is a national road building programme. In Rajasthan it covers new highway stretches and widening work. Progress is reported nationally by the road transport ministry, state by state.','Ministry of Road Transport and Highways','Roads','Rajasthan','Jodhpur',26.2389,73.0243,89000000000,'ongoing','2018-04-01','2027-03-31',NULL,'verified',0.85,now(),true,'official'),
('11111111-1111-1111-1111-111111111117','Varanasi ring road phase 3','A ring road around Varanasi to keep through traffic out of the city.','The ring road lets lorries and long-distance traffic pass Varanasi without entering the old city streets. Phase 3 completes the loop on the eastern side.','National Highways Authority of India','Roads','Uttar Pradesh','Varanasi',25.3176,82.9739,17000000000,'completed','2018-05-01','2022-12-31','2022-11-18','verified',0.87,now(),true,'official'),
('11111111-1111-1111-1111-111111111118','Bhubaneswar smart city drainage and roads','Storm drains and road resurfacing under the smart city programme in Bhubaneswar.','This work rebuilt drains and roads in central Bhubaneswar so that streets clear faster after heavy rain. It was funded under the national smart cities programme.','Bhubaneswar Smart City Limited','Urban civic works','Odisha','Khordha',20.2961,85.8245,4200000000,'completed','2017-06-01','2023-03-31','2023-02-20','verified',0.76,now(),true,'official'),
('11111111-1111-1111-1111-111111111119','Ranchi sewerage network phase 1','A piped sewerage network for central Ranchi.','Before this work most homes in central Ranchi used septic tanks. Phase 1 lays sewer pipes and connects them to a treatment plant so waste water stops reaching open drains.','Jharkhand Urban Infrastructure Development Company','Water and sanitation','Jharkhand','Ranchi',23.3441,85.3096,7900000000,'delayed','2016-09-01','2022-03-31',NULL,'pending_review',0.62,now(),true,'official'),
('11111111-1111-1111-1111-111111111120','Indore city bus depot and electric bus fleet','New electric buses and a depot to charge and service them in Indore.','Indore added electric buses on city routes together with a depot where the buses are charged overnight. Electric buses are quieter and cheaper to run than diesel ones.','Atal Indore City Transport Services','Urban transport','Madhya Pradesh','Indore',22.7196,75.8577,2600000000,'finished_early','2021-07-01','2024-06-30','2023-12-15','verified',0.81,now(),true,'official'),
('11111111-1111-1111-1111-111111111121','Jal Jeevan Mission piped water in Sitapur district','Household tap water connections across villages in Sitapur.','Jal Jeevan Mission aims to give every rural household a working tap. In Sitapur this covers new borewells, overhead tanks and household pipes across many villages.','Ministry of Jal Shakti','Water and sanitation','Uttar Pradesh','Sitapur',27.5680,80.6820,15600000000,'ongoing','2020-04-01','2026-03-31',NULL,'verified',0.83,now(),true,'official'),
('11111111-1111-1111-1111-111111111122','Coimbatore Ukkadam integrated bus terminus','A new bus terminus at Ukkadam in Coimbatore.','The terminus brings town and district buses into one place with waiting areas, toilets and parking, replacing crowded roadside stops.','Coimbatore City Municipal Corporation','Urban transport','Tamil Nadu','Coimbatore',10.9925,76.9614,4500000000,'ongoing','2022-02-01','2026-12-31',NULL,'pending_review',0.60,now(),true,'official'),
('11111111-1111-1111-1111-111111111123','Thiruvananthapuram Vizhinjam port phase 1','A deep water container port at Vizhinjam near Thiruvananthapuram.','Vizhinjam is a deep water port, which means very large container ships can dock without extra dredging. Phase 1 covers the first berths and the breakwater.','Kerala Ports Department','Ports','Kerala','Thiruvananthapuram',8.3776,76.9930,88670000000,'completed','2015-12-01','2024-12-31','2024-12-03','verified',0.89,now(),true,'official'),
('11111111-1111-1111-1111-111111111124','Shillong bypass and Umiam road strengthening','Road strengthening and a bypass on the Shillong approach in Meghalaya.','Hill roads wash out in heavy rain. This work strengthens the road surface and slopes on the approach to Shillong and adds a bypass so through traffic avoids the town centre.','Meghalaya Public Works Department','Roads','Meghalaya','East Khasi Hills',25.5788,91.8933,6100000000,'ongoing','2021-11-01','2026-09-30',NULL,'pending_review',0.57,now(),true,'official'),
('11111111-1111-1111-1111-111111111125','Srinagar Jhelum riverfront and flood channel work','Flood protection and riverfront work along the Jhelum in Srinagar.','After the 2014 floods, the flood spill channel was widened and embankments strengthened so that high water can pass Srinagar without flooding homes.','Jammu and Kashmir Irrigation and Flood Control Department','Flood control','Jammu and Kashmir','Srinagar',34.0837,74.7973,15000000000,'delayed','2016-03-01','2023-12-31',NULL,'pending_review',0.63,now(),true,'official'),
('11111111-1111-1111-1111-111111111126','Ludhiana Buddha Nullah rejuvenation','Cleaning and treatment work on the Buddha Nullah drain in Ludhiana.','Buddha Nullah carries city and industrial waste water into the Sutlej. This project builds treatment capacity and rebuilds the drain walls so less untreated waste reaches the river.','Punjab Municipal Infrastructure Development Company','Water and sanitation','Punjab','Ludhiana',30.9010,75.8573,8400000000,'ongoing','2020-08-01','2026-03-31',NULL,'pending_review',0.59,now(),true,'official')
INSERT INTO public.projects (id, name, plain_summary, details, department, sector, state, district, latitude, longitude, budget_inr, status, start_date, planned_end_date, actual_end_date, verification_status, confidence, last_verified_at, published, source_origin, community_note)
VALUES
('11111111-1111-1111-1111-111111111127','Old Madiwala to Bommanahalli service road resurfacing','A road resurfacing job in south Bengaluru that official records closed years ago.','The official record shows this road was resurfaced and the work closed. People who use it every day report broken edges, sunken patches and standing water after rain. The official closure and the condition on the ground are shown separately here.','Bruhat Bengaluru Mahanagara Palike','Roads','Karnataka','Bengaluru Urban',12.9166,77.6101,320000000,'completed','2017-01-15','2018-03-31','2018-03-28','verified',0.72,now(),true,'community','Listed after a community member reported the road''s present condition. The completion is an official fact; the condition reports below come from the public.')
