INSERT INTO public.candidate_projects (name, plain_summary, department, state, district, proposed_status, citations, agent_confidence, discovered_from, review_state, origin, submitter_name, is_anonymous, category, location_text, observed_condition, completion_date, approximate_date_note, photos, moderation_label, moderation_state, moderation_notes)
VALUES
('Kanpur Ghantaghar to Jajmau road widening','A road widening job in Kanpur that residents say was finished years ago but has broken badly since.','Kanpur Nagar Nigam','Uttar Pradesh','Kanpur Nagar','completed','[]'::jsonb,0,'Community submission','discovered','community','Verified local resident',true,'Roads','Ghantaghar to Jajmau stretch, Kanpur','The widened lanes have sunk near the drains. After rain the left lane holds water for days and two wheelers move into the fast lane.','2019-06-30','Residents recall it opening around mid 2019.','[]'::jsonb,'clean','visible','Nothing flagged.'),
('Sivakasi town primary health centre building','A health centre building in Sivakasi that community members say is finished on paper but barely usable.','Tamil Nadu Health Department','Tamil Nadu','Virudhunagar','completed','[]'::jsonb,0,'Community submission','discovered','community','asha',false,'Health','Near the bus stand, Sivakasi','The building is standing but two wards have no water supply and the ramp ends in a step. Staff use only the front rooms.','2021-03-31','Approximate. A board outside gives 2021.','[]'::jsonb,'possible_unverified_claim','held','This makes a serious allegation, so a reviewer will read it before it appears publicly.');
